update public.paroquias set endereco = case when endereco = '' then 'Anel Viário da UFRN, s/n' else endereco end, bairro = case when bairro = '' then 'Lagoa Nova' else bairro end, cidade = case when cidade = '' then 'Natal' else cidade end
