insert into public.notas_paroquia (paroquia_id, texto, fontes, confianca) values ('ede1a8f3-6a14-505d-b391-01208948c13c', 'A Arquidiocese lista a ''Capela do Campus (UFRN)'' entre as igrejas da Paróquia de Santo Afonso (missa domingo 18h30). O CEP da planilha (59077010) é da Rua Joaquim Alves, não do campus; o OpenStreetMap põe a capela no Anel Viário com CEP genérico 59077-000. CEP deixado vazio. É capela ecumênica: sem padroeiro.', '{"https://www.arquidiocesedenatal.org.br/post/par%C3%B3quia-de-santo-afonso-maria-de-lig%C3%B3rio-mirassol-natal","https://viacep.com.br/ws/59077010/json/","https://www.openstreetmap.org/way/45978794"}', 'media') on conflict (paroquia_id) do nothing;
update public.paroquias set endereco = case when endereco = '' then 'Av. Alto Monte Belo, 123 (Comunidade Betânia)' else endereco end, bairro = case when bairro = '' then 'Neópolis' else bairro end, cep = case when cep = '' then '59086375' else cep end, cidade = case when cidade = '' then 'Natal' else cidade end, padroeiro = case when padroeiro = '' then 'Beata Lindalva Justo de Oliveira' else padroeiro end
  where id = '993cf7da-e2ea-552c-9ac8-a828823d5706' and conferida_em is null;
insert into public.notas_paroquia (paroquia_id, texto, fontes, confianca) values ('993cf7da-e2ea-552c-9ac8-a828823d5706', 'A Arquidiocese confirma a ''Capela da Beata Lindalva Justo (Comunidade Betânia)'' na Paróquia de Cristo Rei (missa sábado 19h), mas não dá o endereço. O nome oficial da rua é Avenida Alto Monte Belo (sem ''do''), CEP 59086-375, Neópolis (ViaCEP). O número 123 vem só da planilha.', '{"https://www.arquidiocesedenatal.org.br/post/par%C3%B3quia-de-cristo-rei-pirangi-natal","https://viacep.com.br/ws/59086375/json/"}', 'media') on conflict (paroquia_id) do nothing;
update public.paroquias set endereco = 'Alameda Boliviana, s/n', bairro = 'Candelária', cep = '59064747', cidade = 'Natal', padroeiro = 'Mãe Peregrina (Nossa Senhora)', lat = -5.843583, lng = -35.212159
  where id = 'f3cc3796-c949-547b-9b36-32a1a95ed35c' and conferida_em is null;
insert into public.notas_paroquia (paroquia_id, texto, fontes, confianca) values ('f3cc3796-c949-547b-9b36-32a1a95ed35c', 'Confirmada pela Arquidiocese como ''Capela da Mãe Peregrina – Bairro Latino'' da Paróquia da Candelária (missa sábado e domingo 16h). O OpenStreetMap também a põe na Alameda Boliviana.', '{"https://www.arquidiocesedenatal.org.br/post/par%C3%B3quia-de-nossa-senhora-da-candel%C3%A1ria-candel%C3%A1ria-natal","https://viacep.com.br/ws/59064747/json/","https://www.openstreetmap.org/node/506553342"}', 'alta') on conflict (paroquia_id) do nothing;
update public.paroquias set endereco = case when endereco = '' then 'Rua Andrelândia, s/n (1ª etapa do Conj. Pirangi)' else endereco end, bairro = case when bairro = '' then 'Neópolis' else bairro end, cep = case when cep = '' then '59084150' else cep end, cidade = case when cidade = '' then 'Natal' else cidade end, padroeiro = case when padroeiro = '' then 'Nossa Senhora de Lourdes' else padroeiro end
  where id = '6cf26871-9708-55cc-a0ee-e6db657adeea' and conferida_em is null;
insert into public.notas_paroquia (paroquia_id, texto, fontes, confianca) values ('6cf26871-9708-55cc-a0ee-e6db657adeea', 'DIVERGÊNCIA: a planilha põe esta capela na R. São Vicente, 40, Felipe Camarão, mas a Arquidiocese diz que a Capela de N. Sra. de Lourdes da Paróquia de Cristo Rei fica na 1ª etapa do Conj. Pirangi (Neópolis), do outro lado da cidade. O OpenStreetMap marca a capela na Rua Andrelândia, Neópolis. O endereço de Felipe Camarão pode ser de outra capela (aquele bairro é da Paróquia de N. Sra. Auxiliadora): conferir antes de publicar.', '{"https://www.arquidiocesedenatal.org.br/post/par%C3%B3quia-de-cristo-rei-pirangi-natal","https://viacep.com.br/ws/59084150/json/","https://www.openstreetmap.org/way/480869086"}', 'media') on conflict (paroquia_id) do nothing;
update public.paroquias set endereco = 'Praça Augusto Leite, s/n (Rua Joaquim Fagundes, 624)', bairro = 'Barro Vermelho', cep = '59020380', cidade = 'Natal', padroeiro = 'Nossa Senhora Rainha da Paz e Santa Luzia', lat = -5.800184, lng = -35.203493
  where id = '0e9fad75-1eb2-5ebe-935a-3509392db133' and conferida_em is null;
insert into public.notas_paroquia (paroquia_id, texto, fontes, confianca) values ('0e9fad75-1eb2-5ebe-935a-3509392db133', 'DUPLICADA: é a mesma capela do item ''Capela Rainha da Paz (Paróquia de Nossa Senhora das Graças e Santa Teresinha)''. A Arquidiocese a chama ''Capela N. Sra. Rainha da Paz e Santa Luzia (Praça Augusto Leite)'', da Paróquia de N. Sra. das Graças e Santa Teresinha (Tirol). A praça fica na Rua Joaquim Fagundes; pelos Correios, praça e rua são do bairro Barro Vermelho, não Tirol (CEP da praça 59020-380; o da rua, 59022-500).', '{"https://www.arquidiocesedenatal.org.br/post/par%C3%B3quia-de-nossa-senhora-das-gra%C3%A7as-e-santa-teresinha-tirol-natal","https://viacep.com.br/ws/59020380/json/","https://viacep.com.br/ws/59022500/json/"}', 'alta') on conflict (paroquia_id) do nothing;
update public.paroquias set endereco = 'Praça Augusto Leite, s/n (Rua Joaquim Fagundes, 624)', bairro = 'Barro Vermelho', cep = '59020380', cidade = 'Natal', padroeiro = 'Nossa Senhora Rainha da Paz e Santa Luzia', lat = -5.800184, lng = -35.203493
  where id = 'ef4891c6-ed39-530d-a4cd-5f1cf6967cba' and conferida_em is null;
insert into public.notas_paroquia (paroquia_id, texto, fontes, confianca) values ('ef4891c6-ed39-530d-a4cd-5f1cf6967cba', 'DUPLICADA do item ''Capela Nossa Senhora Rainha da Paz e Santa Luzia'' (mesmo endereço). Nome oficial na Arquidiocese: ''Capela N. Sra. Rainha da Paz e Santa Luzia (Praça Augusto Leite)''. Manter só um dos dois. Bairro pelos Correios: Barro Vermelho.', '{"https://www.arquidiocesedenatal.org.br/post/par%C3%B3quia-de-nossa-senhora-das-gra%C3%A7as-e-santa-teresinha-tirol-natal","https://viacep.com.br/ws/59020380/json/"}', 'alta') on conflict (paroquia_id) do nothing;
