insert into public.notas_paroquia (paroquia_id, texto, fontes, confianca) values ('53a2059b-0630-5ea8-8e27-836e99b88f47', 'A Arquidiocese confirma a ''Igreja de Santo Antônio - Avenida Senador Salgado Filho'' da Paróquia de São João Batista (missas qui 18h30, sáb 17h, dom 8h30), sem número. O CEP da planilha (59075000) cobre só os números 1900 a 2860 (lado par); para o número 1800 o CEP é 59056-000. Número não confirmado em fonte oficial.', '{"https://www.arquidiocesedenatal.org.br/post/par%C3%B3quia-de-s%C3%A3o-jo%C3%A3o-batista-lagoa-seca-natal","https://viacep.com.br/ws/59056000/json/","https://viacep.com.br/ws/59075000/json/"}', 'media') on conflict (paroquia_id) do nothing;
update public.paroquias set endereco = 'R. Expedicionário Aderbal da Câmara, s/n', bairro = 'Nossa Senhora de Nazaré', cep = '59060390', cidade = 'Natal', padroeiro = 'Nossa Senhora de Nazaré', lat = -5.81726, lng = -35.234259
  where id = '91974767-89df-53fc-abd9-b2cb7def5fae' and conferida_em is null;
insert into public.notas_paroquia (paroquia_id, texto, fontes, confianca) values ('91974767-89df-53fc-abd9-b2cb7def5fae', 'Confirmada pela Arquidiocese como capela da Paróquia dos Santos Mártires (missa sábado 7h e 1ª sexta 19h). O OpenStreetMap a põe nessa rua. Número não encontrado.', '{"https://www.arquidiocesedenatal.org.br/post/par%C3%B3quia-do-santu%C3%A1rio-dos-santos-m%C3%A1rtires-de-cunha%C3%BA-e-urua%C3%A7u-nazar%C3%A9-natal","https://viacep.com.br/ws/59060390/json/","https://www.openstreetmap.org/node/2827025887"}', 'alta') on conflict (paroquia_id) do nothing;
