insert into public.notas_paroquia (paroquia_id, texto, fontes, confianca) values ('d7d3aa4e-c702-55f6-ab3b-c1b9e4fb3b02', 'Confirmada pela Arquidiocese (''Capela de Santana e São Joaquim - Praia do Meio'', Paróquia de N. Sra. de Lourdes, missa domingo 7h). Endereço e número só da planilha; o CEP é da Rua do Motor (que tem vários CEPs). Nome correto: Sant''Ana (com apóstrofo).', '{"https://www.arquidiocesedenatal.org.br/post/par%C3%B3quia-de-nossa-senhora-de-lourdes-areia-preta-natal","https://viacep.com.br/ws/59010090/json/"}', 'media') on conflict (paroquia_id) do nothing;
update public.paroquias set endereco = case when endereco = '' then 'R. Trampolim da Vitória, 46 (Comunidade do Areado)' else endereco end, bairro = case when bairro = '' then 'Cidade Alta' else bairro end, cep = case when cep = '' then '59025747' else cep end, cidade = case when cidade = '' then 'Natal' else cidade end, padroeiro = case when padroeiro = '' then 'São Félix' else padroeiro end
