insert into public.notas_paroquia (paroquia_id, texto, fontes, confianca) values ('6e6c59a9-a526-5a58-bd8b-f1baeddbe8bd', 'A Arquidiocese confirma a ''Capela de São Félix (Comunidade do Areado)'' da Paróquia de N. Sra. da Apresentação (missa domingo 9h30). O CEP da planilha (59025735) é da Travessa Santo Afonso; o da Rua Trampolim da Vitória, Cidade Alta, é 59025-747. A Vila Areado fica nessa rua (OpenStreetMap). Número só da planilha.', '{"https://www.arquidiocesedenatal.org.br/post/par%C3%B3quia-de-nossa-senhora-da-apresenta%C3%A7%C3%A3o-cidade-alta-natal","https://viacep.com.br/ws/59025747/json/","https://viacep.com.br/ws/59025735/json/"}', 'media') on conflict (paroquia_id) do nothing;
update public.paroquias set endereco = case when endereco = '' then 'Av. Romualdo Galvão, 933' else endereco end, bairro = case when bairro = '' then 'Lagoa Seca' else bairro end, cep = case when cep = '' then '59022275' else cep end, cidade = case when cidade = '' then 'Natal' else cidade end, site = case when site = '' then 'https://www.reviverpelamisericordia.com.br' else site end
  where id = 'd0950be4-24aa-5c16-aecb-5d422fd55384' and conferida_em is null;
insert into public.notas_paroquia (paroquia_id, texto, fontes, confianca) values ('d0950be4-24aa-5c16-aecb-5d422fd55384', 'DIVERGÊNCIA: a planilha diz R. Lafayete Lamartine, 1934, Candelária; a página ''Comunidades de vida'' da Arquidiocese diz Rua Romualdo Galvão, 933, Lagoa Seca, 59022-275 (é avenida, pelos Correios). Não achei fonte que confirme a da planilha (pode ser endereço novo). É comunidade de vida, não igreja paroquial. O telefone e o e-mail que a Arquidiocese publica são dos responsáveis (pessoais): não usados. O site existe mas está desatualizado.', '{"https://www.arquidiocesedenatal.org.br/comunidades-de-vida","https://viacep.com.br/ws/59022275/json/","https://www.reviverpelamisericordia.com.br"}', 'media') on conflict (paroquia_id) do nothing;
update public.paroquias set endereco = 'Av. Prof. João Machado, 209 (Conj. dos Professores)', bairro = 'Capim Macio', cep = '59078340', cidade = 'Natal', padroeiro = 'Santo Agostinho', tipo = 'capela'
  where id = '0f4bcffe-6ec2-5ce1-a985-6a7afb9e270e' and conferida_em is null;
insert into public.notas_paroquia (paroquia_id, texto, fontes, confianca) values ('0f4bcffe-6ec2-5ce1-a985-6a7afb9e270e', 'Não é paróquia (a planilha marca tipo ''paroquia''): é igreja da Paróquia de Santo Afonso Maria de Ligório, segundo a Arquidiocese (''Igreja de Santo Agostinho (Conj. dos Professores)'', missas qua 17h, sáb 9h e 19h, dom 11h e 17h). O OpenStreetMap a põe na Av. Prof. João Machado. Contato é o da paróquia (secretariasantoafonso@gmail.com, 84 3615-2855), não posto aqui.', '{"https://www.arquidiocesedenatal.org.br/post/par%C3%B3quia-de-santo-afonso-maria-de-lig%C3%B3rio-mirassol-natal","https://viacep.com.br/ws/59078340/json/","https://www.openstreetmap.org/way/259674263"}', 'alta') on conflict (paroquia_id) do nothing;
