  where id = '836a84c4-2d16-5774-9773-cc84111aca48' and conferida_em is null;
insert into public.notas_paroquia (paroquia_id, texto, fontes, confianca) values ('836a84c4-2d16-5774-9773-cc84111aca48', 'Não é paróquia (a planilha marca tipo ''paroquia''): a Arquidiocese a lista como ''Capela da Beata Ana Rosa Gattorno (Rio Potengi)'', da Paróquia de N. Sra. do Perpétuo Socorro, Quintas (missa domingo 17h). O CEP da planilha (59042203) é da Vila Felizardo Moura; o da Rua Rio Potengi é 59040-580, bairro Quintas pelos Correios (a planilha diz Nordeste). Número só da planilha.', '{"https://www.arquidiocesedenatal.org.br/post/par%C3%B3quia-de-nossa-senhora-do-perp%C3%A9tuo-socorro-quintas-natal","https://viacep.com.br/ws/59040580/json/","https://viacep.com.br/ws/59042203/json/"}', 'media') on conflict (paroquia_id) do nothing;
