  where id = '139ef87c-76a0-5dfa-bc31-09e6e06ff07c' and conferida_em is null;
insert into public.notas_paroquia (paroquia_id, texto, fontes, confianca) values ('139ef87c-76a0-5dfa-bc31-09e6e06ff07c', 'Arquidiocese dá o número 18 (planilha: s/n) e o e-mail da secretaria. Telefone, WhatsApp e Instagram da planilha confirmados.', '{"https://www.arquidiocesedenatal.org.br/post/par%C3%B3quia-de-santa-rita-de-c%C3%A1ssia-dos-imposs%C3%ADveis-ponta-negra-natal","https://www.arquidiocesedenatal.org.br/vicariato-urbano"}', 'alta') on conflict (paroquia_id) do nothing;
