  where id = '0154e5dc-fb39-5b0d-a4b4-10541669fe7d' and conferida_em is null;
insert into public.notas_paroquia (paroquia_id, texto, fontes, confianca) values ('0154e5dc-fb39-5b0d-a4b4-10541669fe7d', 'DIVERGÊNCIAS: a Arquidiocese dá ''Praça da Matriz, s/n, 59070-100'' (planilha: Av. Pernambuco, 1, 59070-300). Instagram oficial na Arquidiocese é @santuariodaesperanca (perfil ''Santuário da Esperança'', ~12 mil seguidores); ''pascomesperanca'' da planilha é o Facebook da Pascom. O telefone 3615-2891 é marcado como WhatsApp.', '{"https://www.arquidiocesedenatal.org.br/post/par%C3%B3quia-santu%C3%A1rio-de-nossa-senhora-da-esperan%C3%A7a-e-santo-in%C3%A1cio-de-loyola","https://www.arquidiocesedenatal.org.br/vicariato-urbano","https://www.instagram.com/santuariodaesperanca/"}', 'alta') on conflict (paroquia_id) do nothing;
update public.paroquias set endereco = 'Av. Floriano Peixoto, 674', bairro = 'Tirol', cep = '59020500', cidade = 'Natal', telefone = '8432014559', whatsapp = '8432014559', instagram = 'paroquiadacatedraldenatal', padroeiro = 'Nossa Senhora da Apresentação', lat = -5.788267, lng = -35.203347
  where id = 'd97b8e4d-4b7c-5ba4-b2c0-7c7329f08618' and conferida_em is null;
insert into public.notas_paroquia (paroquia_id, texto, fontes, confianca) values ('d97b8e4d-4b7c-5ba4-b2c0-7c7329f08618', 'Catedral Metropolitana de Nossa Senhora da Apresentação. Endereço que faltava, pela Arquidiocese (a secretaria fica no subsolo, acesso pela Av. Floriano Peixoto; nos Correios a avenida é ''Marechal Floriano Peixoto''). O 3201-4559 é ''Telefone/whatsapp''. Não confundir com a antiga catedral (Matriz de N. Sra. da Apresentação, Cidade Alta). Sem e-mail publicado.', '{"https://www.arquidiocesedenatal.org.br/post/par%C3%B3quia-da-catedral-de-nossa-senhora-da-apresenta%C3%A7%C3%A3o-natal-1","https://www.arquidiocesedenatal.org.br/catedral-metropolitana","https://www.arquidiocesedenatal.org.br/vicariato-urbano"}', 'alta') on conflict (paroquia_id) do nothing;
update public.paroquias set endereco = 'Rua José Luís da Silva, 1415 (Loteamento Nova Aliança)', bairro = 'Nossa Senhora da Apresentação', cep = '59114230', cidade = 'Natal', whatsapp = '84987407850', instagram = 'imaculadanatalzn', padroeiro = 'Imaculada Conceição'
  where id = '8cb629db-b787-5c7a-ae08-4922fa3d0528' and conferida_em is null;
insert into public.notas_paroquia (paroquia_id, texto, fontes, confianca) values ('8cb629db-b787-5c7a-ae08-4922fa3d0528', 'Endereço que faltava, pela Arquidiocese (Zona Norte). DIVERGÊNCIA no Instagram: a Arquidiocese dá @imaculadanatalzn; a planilha tinha @imaculadanatal. Os dois perfis existem com o nome ''Paróquia Imaculada Conceição''; conferir qual está ativo (pode ser troca de usuário ou perfil de outra cidade). A Arquidiocese chama o 98740-7850 de ''Telefone'', a planilha de WhatsApp.', '{"https://www.arquidiocesedenatal.org.br/post/par%C3%B3quia-da-imaculada-concei%C3%A7%C3%A3o-nova-alian%C3%A7a-natal","https://www.arquidiocesedenatal.org.br/cópia-vicariato-urbano","https://viacep.com.br/ws/59114230/json/"}', 'alta') on conflict (paroquia_id) do nothing;
update public.paroquias set endereco = 'Praça Sagrada Família, s/n', bairro = 'Rocas', cep = '59010670', cidade = 'Natal', telefone = '84991438842', instagram = 'sagradafamilianatal', email = 'secparoquiasagradafamilia@gmail.com', padroeiro = 'Sagrada Família'
  where id = '4082bfb0-8b61-5d6e-96ec-f7f8086103a7' and conferida_em is null;
insert into public.notas_paroquia (paroquia_id, texto, fontes, confianca) values ('4082bfb0-8b61-5d6e-96ec-f7f8086103a7', 'A Arquidiocese dá ''Praça Sagrada Família, s/n'' (planilha: R. São Sebastião; o CEP 59010-670 é da Rua São Sebastião, então a praça deve dar para ela). Telefone: a página da paróquia (atualizada em agosto) dá (84) 99143-8842 (celular, sem dizer se é WhatsApp); a lista do vicariato dá o fixo (84) 3615-2812, talvez antigo. A paróquia também cuida do Santuário dos Santos Reis (@santuariodossantosreis). Secretaria: seg a sex, 15h às 19h.', '{"https://www.arquidiocesedenatal.org.br/post/par%C3%B3quia-da-sagrada-fam%C3%ADlia-rocas-natal","https://www.arquidiocesedenatal.org.br/vicariato-urbano"}', 'alta') on conflict (paroquia_id) do nothing;
