insert into public.notas_paroquia (paroquia_id, texto, fontes, confianca) values ('ac9f0c84-304e-5afc-aee1-1c2df9b27921', 'Arquidiocese dá o número 1186 (planilha: s/n) e o CEP 59052-080, que é da Av. Bom Pastor; o da planilha (59052450) é da Rua Severino Soares, Dix-Sept Rosado. O telefone publicado é celular (99129-9333), sem dizer se é WhatsApp. Instagram como a Arquidiocese grafa (com ''_'' no fim), não conferido no próprio Instagram. Secretaria: seg a sex, 8h às 17h.', '{"https://www.arquidiocesedenatal.org.br/post/par%C3%B3quia-jesus-bom-pastor-bom-pastor-natal","https://www.arquidiocesedenatal.org.br/vicariato-urbano","https://viacep.com.br/ws/59052080/json/","https://viacep.com.br/ws/59052450/json/"}', 'alta') on conflict (paroquia_id) do nothing;
