insert into public.notas_paroquia (paroquia_id, texto, fontes, confianca) values ('833059cc-8900-554f-95a9-25d6fbddae2b', 'Planilha confirmada pela Arquidiocese. Uma notícia mais recente da Arquidiocese traz o telefone (84) 3615-2931 (um dígito diferente); a página da paróquia diz 3615-2831. Um diretório cita o site nsaparecidanatal.com.br, não confirmado em fonte oficial. Abrange Neópolis e o Conjunto Jiqui; capela São Judas Tadeu no Jiqui.', '{"https://www.arquidiocesedenatal.org.br/post/par%C3%B3quia-de-nossa-senhora-aparecida-ne%C3%B3polis-natal","https://www.buser.com.br/destinos/pontos-turisticos/rn/natal/paroquia-de-nossa-senhora-aparecida"}', 'alta') on conflict (paroquia_id) do nothing;
