insert into public.notas_paroquia (paroquia_id, texto, fontes, confianca) values ('e71305aa-4172-5a1f-bdb5-496554f1695f', 'CEP: a Arquidiocese diz 59074-310, a planilha dizia 59072-150. Telefone fixo: a página do Vicariato Urbano 01 diz (84) 2131-5519; o (84) 3605-0941 da planilha não apareceu em nenhuma fonte. A página da paróquia lista (84) 99803-1549, igual ao WhatsApp da planilha. Instagram: a Arquidiocese indica @pnsauxiliadorafc; a planilha dizia paroquianossasraauxiliadora (não confirmado).', '{"https://www.arquidiocesedenatal.org.br/post/par%C3%B3quia-de-nossa-senhora-auxiliadora-felipe-camar%C3%A3o-natal-rn","https://www.arquidiocesedenatal.org.br/vicariato-urbano"}', 'alta') on conflict (paroquia_id) do nothing;
