insert into public.notas_paroquia (paroquia_id, texto, fontes, confianca) values ('2e592cb3-4309-5997-8ad6-d262eb5db22d', 'É a matriz da antiga Catedral, na Cidade Alta (a planilha tem a Capela de São Félix e a Igreja do Rosário como locais desta paróquia). Não confundir com a Paróquia da Catedral Metropolitana, que tem página própria na Arquidiocese. A Arquidiocese lista (84) 3615-2808 como telefone e WhatsApp. Instagram @catedralmatriz vem da página da Arquidiocese; o nome sugere a antiga Catedral (matriz), mas vale conferir. E-mail não encontrado.', '{"https://www.arquidiocesedenatal.org.br/post/par%C3%B3quia-de-nossa-senhora-da-apresenta%C3%A7%C3%A3o-cidade-alta-natal"}', 'alta') on conflict (paroquia_id) do nothing;
