insert into public.notas_paroquia (paroquia_id, texto, fontes, confianca) values ('f342db39-28d1-577e-833c-70adde2ee46b', 'É a paróquia de Mãe Luiza (contatos da planilha batem com a página da Arquidiocese). Há outras paróquias de N. Sra. da Conceição na Arquidiocese (Nova Parnamirim, Ceará-Mirim etc.). Uma notícia de festa cita também @imaculadanatalzn, que parece ser de outra paróquia.', '{"https://www.arquidiocesedenatal.org.br/post/par%C3%B3quia-de-nossa-senhora-da-concei%C3%A7%C3%A3o-m%C3%A3e-luiza-natal"}', 'alta') on conflict (paroquia_id) do nothing;
