insert into public.notas_paroquia (paroquia_id, texto, fontes, confianca) values ('6d1d8e4d-22a2-5dc2-a666-c8cf0fbbad21', 'AMBÍGUO: Natal tem DUAS Paróquias de Sant''Ana, e os horários da planilha parecem misturar as duas. (1) Capim Macio: Rua Des. José Gomes da Costa, 1927, CEP 59082-140; tel. (84) 2020-5323 e (84) 99856-8056; e-mail paroquiasantanacm@yahoo.com.br (outra página: paroquiasantanacmacio@yahoo.com.br); Instagram paroquiadesantanacm; matriz: ter-qui 19h, sex e sáb 17h, dom 10h e 17h. (2) Soledade II (Potengi): Av. Ilha de São Paulo, 1110, Conj. Soledade II, CEP 59129-130; tel. (84) 3615-2880; Instagram paroquiadesantanasoledadeii; matriz: dom 7h, 17h e 19h, semana e sábado 17h. Sugestão: separar em duas igrejas.', '{"https://www.arquidiocesedenatal.org.br/post/par%C3%B3quia-de-sant-ana-capim-macio-natal","https://www.arquidiocesedenatal.org.br/post/par%C3%B3quia-de-sant-ana-soledade-2-natal","https://www.arquidiocesedenatal.org.br/vicariato-urbano","https://www.arquidiocesedenatal.org.br/c%C3%B3pia-vicariato-urbano"}', 'media') on conflict (paroquia_id) do nothing;
