insert into public.notas_paroquia (paroquia_id, texto, fontes, confianca) values ('c4a3b311-5163-5b87-b17e-e31812ae9fc0', 'A planilha não dizia qual Paróquia de São José. A única de Natal com esse nome no site da Arquidiocese é a de Cidade Nova (abrange Cidade Nova, Nova Cidade e parte do Planalto); as outras São José são de outras cidades, e a de Lagoa Nova é São José de Anchieta. Conferir se é esta. O Instagram é da Pascom da paróquia.', '{"https://www.arquidiocesedenatal.org.br/post/par%C3%B3quia-de-s%C3%A3o-jos%C3%A9-cidade-nova-natal"}', 'media') on conflict (paroquia_id) do nothing;
