insert into public.notas_paroquia (paroquia_id, texto, fontes, confianca) values ('44d86254-fc28-570f-8b0e-69fb2192935c', 'Igreja de Santo Agostinho no Conjunto dos Professores, comunidade da Paróquia de Santo Afonso (missas aos domingos, 8h e 19h). O endereço da planilha bate com o CEP 59078-340 (Av. Prof. João Machado) e com o Buser; a Arquidiocese não publica o endereço da capela. Contatos: os da paróquia, (84) 3615-2855 (WhatsApp), secretariasantoafonso@gmail.com, Instagram paroquiastoafonso_rn.', '{"https://www.arquidiocesedenatal.org.br/post/par%C3%B3quia-de-santo-afonso-maria-de-lig%C3%B3rio-mirassol-natal","https://arquidiocesedenatal.org.br/conjunto-dos-professores-festeja-santo-agostinho.html","https://www.buser.com.br/destinos/pontos-turisticos/rn/natal/igreja-de-santo-agostinho","https://cepbrasil.org/rio-grande-do-norte/natal/capim-macio/59078340"}', 'media') on conflict (paroquia_id) do nothing;
update public.paroquias set endereco = case when endereco = '' then 'Rua Vital Correia, 492' else endereco end, bairro = case when bairro = '' then 'Nova Descoberta' else bairro end, cep = case when cep = '' then '59570000' else cep end, cidade = case when cidade = '' then 'Ceará-Mirim' else cidade end, instagram = case when instagram = '' then 'nsadasdores' else instagram end, email = case when email = '' then 'nsadasdorescm@gmail.com' else email end, padroeiro = case when padroeiro = '' then 'Nossa Senhora das Dores' else padroeiro end
  where id = 'f0c1b0ae-fabf-5cd0-9c97-83e90a3570db' and conferida_em is null;
insert into public.notas_paroquia (paroquia_id, texto, fontes, confianca) values ('f0c1b0ae-fabf-5cd0-9c97-83e90a3570db', 'Não existe Área Pastoral de Nossa Senhora das Dores em Natal no site da Arquidiocese. A que tem esse nome (endereço da página: area-pastoral-de-nossa-senhora-das-dores-ceara-mirim) fica em CEARÁ-MIRIM e hoje aparece como Paróquia de Nossa Senhora das Dores - Ceará-Mirim. Cidade corrigida. Sem telefone publicado. Conferir se a planilha queria esta.', '{"https://www.arquidiocesedenatal.org.br/post/%C3%A1rea-pastoral-de-nossa-senhora-das-dores-cear%C3%A1-mirim"}', 'media') on conflict (paroquia_id) do nothing;
update public.paroquias set endereco = case when endereco = '' then 'Rua Vereador José Andrade, s/n' else endereco end, bairro = case when bairro = '' then 'Centro' else bairro end, cep = case when cep = '' then '59780000' else cep end, cidade = case when cidade = '' then 'Rio do Fogo' else cidade end, whatsapp = case when whatsapp = '' then '84996333035' else whatsapp end, instagram = case when instagram = '' then 'pascom.navegantes' else instagram end, email = case when email = '' then 'apnsnavegantes@gmail.com' else email end, padroeiro = case when padroeiro = '' then 'Nossa Senhora dos Navegantes' else padroeiro end
  where id = '141b41b5-36d8-5228-af22-ea109ee76d95' and conferida_em is null;
insert into public.notas_paroquia (paroquia_id, texto, fontes, confianca) values ('141b41b5-36d8-5228-af22-ea109ee76d95', 'A Área Pastoral com esse nome no site da Arquidiocese (endereço da página: area-pastoral-de-nossa-senhora-dos-navegantes-rio-do-fogo) fica em RIO DO FOGO, hoje listada como paróquia. Cidade corrigida. Em Natal há a Paróquia de Nossa Senhora dos Navegantes da Redinha (Rua Francisco Ivo, 85, CEP 59122-000, WhatsApp (84) 99849-4501, Instagram pnsnnavegantesredinha), que é paróquia, não área pastoral; conferir qual a planilha queria. O celular aparece como telefone; não diz se é WhatsApp. O Instagram é o da Pascom.', '{"https://www.arquidiocesedenatal.org.br/post/%C3%A1rea-pastoral-de-nossa-senhora-dos-navegantes-rio-do-fogo","https://www.arquidiocesedenatal.org.br/post/par%C3%B3quia-de-nossa-senhora-dos-navegantes-redinha-natal"}', 'media') on conflict (paroquia_id) do nothing;
